    0x0300,0x0301,0x0302,0x0303,0x0304,0x0305,0x0306,0x0307,0x0308,0x0309,0x030A,0x030B,0x030C,0x030D,0x030E,0x030F,
    # Actually combining handled via unicodedata.combining, but keep explicit for some?
    0x200B,0x200C,0x200D,0xFEFF,
    # Additional zero-width from unicode-width tables (common)
    0x00AD, #? No, 00AD is width 1 per test, so NOT zero-width. Exclude.
])
# For simplicity, use combining + control + east_asian + explicit zero-width
# U+00AD should be width 1, so exclude from zero-width
ZERO_WIDTH_SET.discard(0x00AD)
# Add more zero-width ranges: 0x1160-0x11FF? No, those are ... Let's just handle common and fallback to 1.
# From unicode-width: Cf category? But 00AD is Cf with width 1, so can't use category alone.
# We'll use explicit list for known zero-width: 200B-200D, FEFF, and combining.
EXTRA_ZERO = {0x200B,0x200C,0x200D,0xFEFF, 0x2060, 0x180B,0x180C,0x180D, 0xFE00,0xFE01,0xFE02,0xFE03,0xFE04,0xFE05,0xFE06,0xFE07,0xFE08,0xFE09,0xFE0A,0xFE0B,0xFE0C,0xFE0D,0xFE0E,0xFE0F}

def char_width(c):
    o = ord(c)
    # Control C0, DEL, C1
    if o == 0 or (0x01 <= o <= 0x1F) or o == 0x7F or (0x80 <= o <= 0x9F):
        return 0
    # Combining
    try:
        if unicodedata.combining(c) != 0:
            return 0
    except:
        pass
    if o in EXTRA_ZERO or o in ZERO_WIDTH_SET:
        return 0
    # Additional zero-width ranges from unicode-width (simplified): 0x1160-0x11FF? No.
    # East Asian Wide/Fullwidth -> 2
    try:
        eaw = unicodedata.east_asian_width(c)
        if eaw in ('W','F'):
            return 2
    except:
        pass
    return 1

def str_width(s):
    w = 0
    for ch in s:
        cw = char_width(ch)
        if cw is None:
            cw = 0
        w += cw
    return w

