# TOML serialization helpers
def is_forcing_control(ch):
    o = ord(ch)
    if o == 0x09:  # \t allowed
        return False
    if o == 0x0A:  # \n handled separately (multiline)
        return False
    if o == 0x1F or o == 0x7F:
        return False  # bug: not forcing, stays literal
    if 0x01 <= o <= 0x08:
        return True
    if 0x0B <= o <= 0x0D:  # \v, \f, \r (0x0B,0x0C,0x0D)
        # 0x0B \v, 0x0C \f, 0x0D \r
        return True
    if 0x0E <= o <= 0x1E:
        return True
    return False

def has_forcing(s):
    for ch in s:
        if is_forcing_control(ch):
            return True
    return False

def escape_double_content(s, is_multiline):
    # Escape for double/triple-double (basic strings)
    # is_multiline True: \n stays literal newline, else \n would be... but single-line has no \n, so same
    res = []
    for ch in s:
        o = ord(ch)
        if ch == '\\':
            res.append('\\\\')
        elif ch == '"':
            res.append('\\"')
        elif ch == '\b':  # 0x08
            res.append('\\b')
        elif ch == '\t':  # 0x09
            res.append('\\t')
        elif ch == '\n':
            if is_multiline:
                res.append('\n')
            else:
                res.append('\\n')
        elif ch == '\f':  # 0x0C
            res.append('\\f')
        elif ch == '\r':  # 0x0D
            res.append('\\r')
        elif o == 0x1F or o == 0x7F:
            res.append(ch)  # bug: literal
        elif 0x01 <= o <= 0x1F:
            # Other controls: \uXXXX uppercase
            # Note: 0x0B \v => \u000B, etc.
            res.append('\\u%04X' % o)
        else:
            res.append(ch)
    return ''.join(res)

def toml_escape_value(s):
    # Returns TOML representation for string value (command/description/tags element)
    has_nl = '\n' in s
    if has_nl:
        # multiline
        needs_triple_double = False
        if "'''" in s:
            needs_triple_double = True
        elif s.endswith("'"):
            needs_triple_double = True
        elif has_forcing(s):
            needs_triple_double = True
        if needs_triple_double:
            esc = escape_double_content(s, True)
            return '"""\n' + esc + '"""'
        else:
            return "'''\n" + s + "'''"
    else:
        # single-line
        if has_forcing(s):
            esc = escape_double_content(s, False)
            return '"' + esc + '"'
        if "'''" in s:
            esc = escape_double_content(s, False)
            return '"' + esc + '"'
        if "'" in s:
            if s.endswith("'"):
                esc = escape_double_content(s, False)
                return '"' + esc + '"'
            else:
                return "'''" + s + "'''"
        else:
            # single, no forcing, no ''', no '
            return "'" + s + "'"

def toml_escape_alias_key(alias):
    # Bare if matches ^[A-Za-z0-9_-]+$ and non-empty? Empty handled as bare (bug)
    if alias == "":
        return ""  # will become [scripts.] (bare empty)
    import re as _re
    if _re.match(r'^[A-Za-z0-9_-]+$', alias):
        return alias
    else:
        # double-quoted with escapes (always double, never single/triple)
        # \n escaped as \n (not multiline), \r as \r, etc.
        res = []
        for ch in alias:
            o = ord(ch)
            if ch == '\\':
                res.append('\\\\')
            elif ch == '"':
                res.append('\\"')
            elif ch == '\b':
                res.append('\\b')
            elif ch == '\t':
                res.append('\\t')
            elif ch == '\n':
                res.append('\\n')
            elif ch == '\f':
                res.append('\\f')
            elif ch == '\r':
                res.append('\\r')
            elif o == 0x1F or o == 0x7F:
                res.append(ch)
            elif 0x01 <= o <= 0x1F:
                res.append('\\u%04X' % o)
            else:
                res.append(ch)
        return '"' + ''.join(res) + '"'

