def parse_toml_key(s, pos, line_starts):
    # Parse key (bare or quoted, possibly dotted) starting at pos, return (key_parts, new_pos)
    # key_parts: list of strings (each part)
    # Also handles whitespace around dots?
    import bisect
    def cur_line(p):
        return bisect.bisect_right(line_starts, p)
    parts = []
    while True:
        while pos < len(s) and s[pos] in ' \t':
            pos += 1
        if pos >= len(s):
            break
        c = s[pos]
        if c == "'" or c == '"':
            # Quoted key: '...' or "..." (single-line only? Keys can't be multiline? TOML keys can be basic/literal strings, single-line only)
            is_single = (c == "'")
            # Check for triple? Keys shouldn't be triple, but handle? For simplicity, if triple, error? Actually alias with newline as key? Alias "a\nb" as key is "a\nb" with \n escaped, not multiline. So keys are single-line.
            # If s[pos:pos+3] is triple, treat as error? Or handle as triple? For safety, handle triple as well (though shouldn't occur for keys).
            if s[pos:pos+3] == "'''" or s[pos:pos+3] == '"""':
                # Triple key? Unlikely. Treat as triple string?
                val, typ, pos = parse_toml_value(s, pos, line_starts)
                parts.append(val)
            else:
                # Single-line quoted
                quote = c
                pos += 1
                val_chars = []
                while True:
                    if pos >= len(s):
                        ln = cur_line(pos)
                        toml_error(f"newline in string found at line {ln}")
                    ch = s[pos]
                    if ch == '\n' or ch == '\r':
                        ln = cur_line(pos)
                        toml_error(f"newline in string found at line {ln}")
                    if ch == quote:
                        pos += 1
                        break
                    if not is_single and ch == '\\':
                        if pos+1 >= len(s):
